package net.civeira.phylax.feature.observe.observedslo.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.valueobject.ObjectiveVO;

class ObjectiveValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of objective of observed slo")
  void test_objective_value_holder_assign_plain_value() {
    Object holder = new Object();
    ObjectiveValueHolder<Object> value = new ObjectiveValueHolder<>(holder);
    Assertions.assertSame(holder, value.objective(1), "Setters must return the holder");
    Assertions.assertTrue(value.getObjectiveValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getObjective().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of objective of observed slo")
  void test_objective_value_holder_assign_value_object() {
    Object holder = new Object();
    ObjectiveValueHolder<Object> value = new ObjectiveValueHolder<>(holder);
    ObjectiveVO vo = ObjectiveVO.from(1);
    Assertions.assertFalse(value.getObjectiveValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.objective(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getObjectiveValue().orElseThrow());
    Assertions.assertSame(holder, value.objective(Optional.empty()));
    Assertions.assertFalse(value.getObjectiveValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.objective(Optional.of(vo)));
    Assertions.assertSame(vo, value.getObjectiveValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of objective of observed slo against the original")
  void test_objective_value_holder_read() {
    Object holder = new Object();
    ObjectiveValueHolder<Object> value = new ObjectiveValueHolder<>(holder);
    ObjectiveVO vo = ObjectiveVO.from(1);
    ObjectiveVO other = ObjectiveVO.from(1);
    ObservedSlo original = Mockito.mock(ObservedSlo.class);
    Mockito.when(original.getObjectiveValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readObjective(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readObjective(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.objective(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readObjective(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readObjective(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of objective of observed slo")
  void test_objective_value_holder_unset() {
    Object holder = new Object();
    ObjectiveValueHolder<Object> value = new ObjectiveValueHolder<>(holder);
    ObjectiveVO vo = ObjectiveVO.from(1);
    value.objective(vo);
    Assertions.assertSame(holder, value.unsetObjectiveIfMatches("objective_other"));
    Assertions.assertTrue(value.getObjectiveValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetObjectiveIfMatches("objective"));
    Assertions.assertFalse(value.getObjectiveValue().isPresent(),
        "The field name must clear the value");
    value.objective(vo);
    Assertions.assertSame(holder, value.unsetObjective());
    Assertions.assertFalse(value.getObjectiveValue().isPresent(), "Unset must clear the value");
  }
}
